mapper.update:
UPDATE member
SET password = #{password}, updated_at = NOW()
WHERE user_id = #{userId}

UPDATE member
SET profile_img = #{profileImg}
WHERE user_id = #{userId}

UPDATE member
SET status	= 'WITHDRAWN', withdrawn_at = NOW()
WHERE user_seq = #{userSeq}

mapper.select:
SELECT COUNT(*)
FROM member
WHERE user_id = #{userId}

SELECT COUNT(*)
FROM member
WHERE user_name = #{userName}
